Rule: Non-0/non-1 cells are "walls". The structure spans the wall columns (plus any column containing 1s). In each structure column a fill-line is computed: the wall's own top for wall columns, the top of the shorter flanking wall for pocket columns between walls; if 1-runs sit directly capping wall tops at a common level ≥2 rows down, that "lid" level overrides (pair 2's plateau). All 1s above the fill-line are deleted and all empty cells between the fill-line and the wall top/column bottom become 1; walls are never changed. This reproduces all three training pairs exactly (stray corner 1s removed, U/pocket interiors filled), and on the test it deletes the 5 stray 1s at the top-left and fills the only pocket, column 8, rows 5–9.

```python
def solve(x):
    g = [row[:] for row in x]
    H, W = len(g), len(g[0])

    # Walls = structure frames: any color that is neither background(0) nor fill(1).
    tau = {}
    for c in range(W):
        rows = [r for r in range(H) if g[r][c] not in (0, 1)]
        if rows:
            tau[c] = min(rows)
    if not tau:
        return g

    one_cols = {c for c in range(W) if any(g[r][c] == 1 for r in range(H))}
    cmin, cmax = min(tau), max(tau)
    # Structure columns: wall-to-wall span, plus any column already holding 1s.
    S = set(range(cmin, cmax + 1)) | one_cols
    # Columns outside the wall span count only if they already hold 1s.
    S = {c for c in S if cmin <= c <= cmax or c in one_cols}

    # Lid level: contiguous 1-runs capping a wall top directly.
    tops = []
    for c in S:
        if c in tau:
            t = tau[c]
            if t - 1 >= 0 and g[t - 1][c] == 1:
                b = t - 1
                while b - 1 >= 0 and g[b - 1][c] == 1:
                    b -= 1
                tops.append(b)
    good = [t for t in tops if t >= 2]  # a real lid is not hugging the top edge
    lid = min(good) if good else None

    def col_top(c):
        if c in tau:
            base = tau[c]
        else:
            L = next((tau[d] for d in range(c - 1, -1, -1) if d in tau and d in S), None)
            R = next((tau[d] for d in range(c + 1, W) if d in tau and d in S), None)
            cand = [v for v in (L, R) if v is not None]
            if not cand:
                return None
            base = max(cand)  # pocket fills up to the shorter flanking wall
        if lid is not None:
            base = min(base, lid)
        return base

    for c in sorted(S):
        T = col_top(c)
        if T is None:
            continue
        stop = tau[c] if c in tau else H  # wall columns only get a cap zone; pockets run to bottom
        for r in range(H):
            if r < T:
                if g[r][c] == 1:
                    g[r][c] = 0          # stray fill above the structure
            elif r < stop and g[r][c] == 0:
                g[r][c] = 1              # complete the pocket / lid
    return g
